#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 8

int adj[MAX_NODES][MAX_NODES];
int indegree[MAX_NODES];
int done[MAX_NODES];

void topological_sort(int num_nodes) {
    int i, j;
    for (i = 0; i < num_nodes; i++) {
        if (indegree[i] == 0 && !done[i]) {
            done[i] = 1;
            printf("%d ", i);
            for (j = 0; j < num_nodes; j++) {
                if (adj[i][j] == 1) {
                    indegree[j]--;
                }
            }
            topological_sort(num_nodes);
        }
    }
}

int main(int argc, char **argv) {
    int num_nodes = argc - 1;
    if (num_nodes > MAX_NODES) {
        printf("INVALID_INPUT\n");
        return 1;
    }

    // Initialize adjacency matrix and in-degrees
    for (int i = 0; i < num_nodes; i++) {
        for (int j = 0; j < num_nodes; j++) {
            adj[i][j] = 0;
        }
        indegree[i] = 0;
        done[i] = 0;
    }

    // Read edges from command line arguments
    for (int i = 1; i < argc; i += 2) {
        int u = atoi(argv[i]);
        int v = atoi(argv[i + 1]);
        if (u >= num_nodes || v >= num_nodes) {
            printf("INVALID_INPUT\n");
            return 1;
        }
        adj[u][v] = 1;
        indegree[v]++;
    }

    // Check for cycles
    for (int i = 0; i < num_nodes; i++) {
        if (indegree[i] == 0) {
            topological_sort(num_nodes);
            return 0;
        }
    }

    printf("CYCLE\n");
    return 0;
}
